namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int TotalDiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyPartCents(subtotalCents, tier);
        var promoCents = PromoPartCents(subtotalCents - loyaltyCents, promoCode);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }

    private static int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(LoyaltyDiscountPolicy.DiscountCents(subtotalCents, tier), LoyaltyCapCents);

    private static int PromoPartCents(int remainingCents, string? promoCode) =>
        promoCode?.ToUpperInvariant() switch
        {
            "WELCOME5" => Welcome5Cents,
            "SUMMER10" => Math.Min(remainingCents * 10 / 100, Summer10CapCents),
            _ => 0
        };
}

